for i,v in enumerate(jersey.data.vertices):
    row,j=divmod(i,32)
    a=j*math.tau/32
    if row<=2:
        forward=max(0,math.cos(a))
        drop=max(0,1-abs(math.sin(a)))*forward
        v.co.z-=(42,29,12)[row]*unit*drop
        v.co.y-=unit*(18,12,5)[row]*drop
        v.co.x*=1.15 if row==0 else 1
