# Outer panels follow the established coat envelope, sampled in its rest pose.
def surface(ob,x,z):
    hit,loc,_,_=ob.ray_cast(Vector(wp(x,-160,z)),Vector((0,1,0)))
    return loc.y/unit if hit else None
def patch(name,rows,mirror,m,ob,offset=1.4):
    vs=[];fs=[]
    for z,left,right in rows:
        for j in range(9):
            x=mirror*(left+(right-left)*j/8)
            y=surface(ob,x,z)
            if y is None:
                # The lapel folds across the coat opening.
                y=-36 if z<163 else -41-(min(z,207)-163)*.17
            vs.append(wp(x,y-offset,z))
        if len(vs)>9:
            k=len(vs)-18
            for j in range(8):fs.append((k+j,k+9+j,k+10+j,k+j+1))
    ob2=geo(name,vs,fs,m)
    for p in ob2.data.polygons:p.use_smooth=True
    return ob2
